// Δείγματα αληθινών φωνών (χορωδία) για την Οκτώηχο.
// Πηγή: gleitz/midi-js-soundfonts — MusyngKite (CC BY-SA 3.0) και FluidR3_GM (CC BY 3.0). Επεξεργασία: κούρδισμα, εξίσωση έντασης. Έκδοση 19-10-2026 (μορφή ADPCM).
// Η χορωδία είναι σε απλή μορφή (IMA ADPCM), που την ανοίγει το ίδιο το πρόγραμμα:
// έτσι δεν εξαρτάται από τον browser (στο iPhone η αποκωδικοποίηση mp3 μπορεί να αποτύχει σιωπηλά).
window.FONI_ADPCM=(function(){
  const STEP=[7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767];
  const IDX=[-1,-1,-1,-1,2,4,6,8];
  const cache=new Map();
  function pcm(n){
    if(cache.has(n)) return cache.get(n);
    const bin=atob(n.adpcm), N=n.len, a=new Float32Array(N);
    let pred=0, ix=0;
    for(let i=0;i<N;i++){
      const byte=bin.charCodeAt(i>>1), code=(i&1)?(byte>>4):(byte&15), st=STEP[ix];
      let diff=st>>3; if(code&4) diff+=st; if(code&2) diff+=st>>1; if(code&1) diff+=st>>2;
      pred=(code&8)?pred-diff:pred+diff; if(pred>32767) pred=32767; else if(pred<-32768) pred=-32768;
      ix+=IDX[code&7]; if(ix<0) ix=0; else if(ix>88) ix=88;
      a[i]=pred/32768;
    }
    cache.set(n,a); return a;
  }
  // Επιστρέφει έτοιμο AudioBuffer για μία νότα του σετ
  return function(ctx,n){ const a=pcm(n), b=ctx.createBuffer(1,a.length,n.sr); b.getChannelData(0).set(a); return b; };
})();
